examples.template:
VStack(alignment: .leading) {
    MonarchButton({{arrangeLabel}}, variant: isEditing ? .primary : .secondary, size: .sm) {
        isEditing.toggle()
    }
    MonarchDashboardGrid(
        tiles,
        layout: $layout,
        itemLabel: \.title,
        span: { $0.span },
        isEditing: isEditing,
        content: { tile in
            MonarchWidget(tile.title) {
                Text(tile.body).monarchTextStyle(.body)
            }
        }
    )
    Text("Saved layout: \(layout.joined(separator: ", "))").monarchTextStyle(.caption)
}

examples.setupTemplate:
struct Tile: Identifiable {
    let id: String
    let title: String
    let body: String
    var span: MonarchDashboardGridSpan = .one
}

private let tiles = [
    Tile(id: {{widgets.0.id}}, title: {{widgets.0.title}}, body: {{widgets.0.body}}, span: .{{widgets.0.span|raw}}),
    Tile(id: {{widgets.1.id}}, title: {{widgets.1.title}}, body: {{widgets.1.body}}, span: .columns({{widgets.1.span}})),
    Tile(id: {{widgets.2.id}}, title: {{widgets.2.title}}, body: {{widgets.2.body}}),
]
@State private var layout: [String] = [{{layout.0}}, {{layout.1}}, {{layout.2}}]
@State private var isEditing = false

